#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr putWaterFX ( FSSpec &theMeshFSSpec );OSErr putWaterFX ( FSSpec &theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	OSErr		theError;	unsigned char *theMap;	int i, j, k, l, x, y;	long theSize, theWidth, theHeight;	long PictureSize, PictureWidth, PictureHeight;	int				colorCounter[257];	unsigned int		maxColor;	struct meshHeader theMeshHeader;	struct gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	theWidth = theMeshHeader.meshWidth * 16;	theHeight = theMeshHeader.meshHeight * 16;	theSize =  theWidth * theHeight;	PictureWidth = theWidth * 16;	PictureHeight = theHeight * 16;	PictureSize = PictureWidth * PictureHeight;	theGrid = (struct gridData *) NewPtr (theSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	theMap = (unsigned char *) NewPtr ( PictureSize );	if ( theMap == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theError = readBMP ( "\p:Graphics.in:waterfx.bmp", PictureWidth, PictureHeight, nil, (char *) theMap );	if ( theError != noErr ){		DisposePtr ( (Ptr) theMap );		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return theError;	}		for ( y = 0, i = 0; y < PictureSize - PictureWidth * 15; y += PictureWidth * 16 ){		for ( x = PictureWidth - 16; x >= 0; x -= 16, i++ ){			for (l = 0; l < 256; l++ )				colorCounter[l] = 0;			for ( k = 0; k < 16; k++ )				for ( j = 0; j < 16; j++ )					colorCounter[ theMap[x + y + j + k * PictureWidth] ]++;			maxColor = 0;			for (l = 0; l < 256; l++ )				if ( colorCounter[l] >= maxColor )					maxColor = l;			theGrid[i].water = maxColor;		}	}	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) theMap );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );	return	noErr;}